-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["433e31165671be7d"] = { "Della terribile guerra che ne seguì tra i seguaci di Hakkar e il resto delle tribù Gurubashi si parla soltanto sottovoce. Il nascente impero fu frantumato dalla magia scatenata tra il dio adirato e i suoi figli ribelli. Proprio quando la battaglia sembrava ormai senza speranza, i troll riuscirono a distruggere l'avatar di Hakkar e a bandirlo dal mondo.", "." },
  ["434212c58a92ca70"] = { "Kil'jaeden scagliò il blocco di ghiaccio attraverso le dimensioni fino ad Azeroth, dove atterrò sul continente di Nordania, portando questo grande male nel nostro mondo. Ner'zhul era scomparso per sempre; al suo posto c'era un trono di ghiaccio e di odio. Quello che un tempo era un rispettato capo sciamano era diventato il potentissimo Re dei Lich.", "." },
  ["4349b4d9d18c85f5"] = { "La preda portò un'aria di festa nella spedizione. Barnil versò idromele per tutti. Ma i nostri festeggiamenti durarono poco. Mentre preparavamo la carcassa per trasportarla al campo base, fummo tutti colti alla sprovvista da un ringhio orrendo. In tutti i miei anni non avevo mai sentito niente di così raccapricciante.", "." },
  ["43528f38b2466284"] = { "Sorgendo dall'oceano, torre d'acqua, Neptulon mandò i grandi Krakken contro la condannata I'lalai. Così immense erano le loro forme che foreste di alghe ondeggiavano fra le loro membra, e leviatani nuotavano attraverso i loro corpi.\n\nIl più grande dei Krakken alzò allora le braccia e le abbatté sul mare, sollevando onde attorno a sé. E le onde si scagliarono furiose verso I'lalai.", "." },
  ["4365a2ab2bf6f95f"] = { "Ho trovato un modo per entrare nella Chamber of Khaz'mul!\n\nPrendi il Medaglione di Gni'kiv dal mio baule.\n\nSconfiggi il trogg Revelosh nella camera prima della sala delle mappe e recupera la Staffa di Tsol.\n\nUnisci il medaglione e la staffa per creare il ⟦Staff of Prehistoria=Bastone della Preistoria⟧.\n\nUsa il bastone nella sala delle mappe per aprire la porta della Chamber of Khaz'mul.\n\nFai queste cose, e la camera sarà tua!\n-Baelog", "." },
})
